for (const q of queries) {
  out[q] = await tools.search({query: q, limit: 8});
}
return Object.fromEntries(Object.entries(out).map(([k,v]) => [k, v.items.map(i => i.path)]));

const queries = ["bash", "terminal", "zsh", "cmd", "shell command", "write file", "edit file", "filesystem", "read file", "test runner", "build"];
const out = {};
for (const q of queries) {
  const r = await tools.search({query: q, limit: 10});
  out[q] = r.items.map(i => i.path + " :: " + i.description.slice(0, 60));
}
return out;

