1: /* ==========================================================================
2:    Pixel sky header (px): the day and storm scenes that PixelSky draws,
3:    the text plates that sit on top of them, and the mascot. The art grid
4:    is 320 by 32 units and the band is whatever height the header content
5:    makes it, so the scene scales with slice and the horizon always lands
6:    on the bottom edge: one unit of artwork stays a chunky, square pixel
7:    from a phone to a judging table. Nothing here is a raster image, so
8:    image rendering pixelated only guards the logo for the day a bitmap
9:    replaces it. Motion is gated behind prefers-reduced-motion:
10:    no-preference, matching the rest of the app.
11:    ========================================================================== */
12: 
13: .px-header {
14:   position: relative;
15:   display: flex;
16:   align-items: center;
17:   overflow: hidden;
18:   min-height: clamp(120px, 12vw, 184px);
19:   background: #b0d9ff;
20:   border-bottom: 3px solid var(--rp-paper);
21: }
22: 
23: .px-sky {
24:   position: absolute;
25:   inset: 0;
26:   display: block;
27:   width: 100%;
28:   height: 100%;
29: }
30: 
31: /* A text plate: solid white card, chunky border, hard offset shadow,
32:    so the title keeps AA contrast on the pale day sky and on the
33:    indigo storm sky without the art having to dim itself. */
34: 
35: .px-plate {
36:   display: flex;
37:   align-items: center;
38:   gap: var(--rp-s3);
39:   max-width: 100%;
40:   padding: var(--rp-s2) var(--rp-s3);
41:   background: var(--rp-panel);
42:   border: 3px solid var(--rp-paper);
43:   box-shadow: 5px 5px 0 0 var(--cp-shadow-strong);
44: }
45: 
46: .px-plate img {
47:   image-rendering: pixelated;
48: }
49: 
50: .px-title {
51:   margin: 0;
52:   font-family: var(--rp-font-pixel);
53:   font-weight: 700;
54:   font-size: clamp(1rem, 3vw, 1.5rem);
55:   line-height: 1.3;
56:   letter-spacing: 0.02em;
57:   color: var(--rp-paper);
58: }
59: 
60: .px-tagline {
61:   margin: var(--rp-s1) 0 0;
62:   max-width: 46ch;
63:   font-size: 0.75rem;
64:   line-height: 1.5;
65:   color: var(--rp-text-dim);
66: }
67: 
68: .px-track {
69:   margin: 0;
70:   padding: var(--rp-s1) var(--rp-s3);
71:   background: var(--rp-panel);
72:   border: 2px solid var(--rp-paper);
73:   box-shadow: 3px 3px 0 0 var(--cp-shadow-strong);
74:   font-family: var(--rp-font-pixel);
75:   font-size: 0.625rem;
76:   line-height: 1.7;
77:   letter-spacing: 0.12em;
78:   text-transform: uppercase;
79:   color: var(--rp-text-dim);
80: }
81: 
82: .px-mascot {
83:   display: block;
84:   flex: none;
85:   width: 64px;
86:   height: 64px;
87: }
88: 
89: /* ==========================================================================
90:    Motion: the rain falls in whole pixel steps and the bolt flickers.
91:    Only when motion is welcome; the global prefers-reduced-motion: reduce
92:    block in src/index.css zeroes the durations a second time.
93:    ========================================================================== */
94: 
95: @media (prefers-reduced-motion: no-preference) {
96:   .px-sky__rain {
97:     animation: px-rain-fall 360ms steps(4, end) infinite;
98:   }
99: 
100:   .px-sky__bolt {
101:     animation: px-bolt-flicker 2.4s linear infinite;
102:   }
103: }
104: 
105: /* Eight units is one full drop, so the loop closes without a seam. */
106: @keyframes px-rain-fall {
107:   from {
108:     transform: translateY(-8px);
109:   }
110: 
111:   to {
112:     transform: translateY(0);
113:   }
114: }
115: 
116: @keyframes px-bolt-flicker {
117:   0%,
118:   86% {
119:     opacity: 1;
120:   }
121: 
122:   87%,
123:   92% {
124:     opacity: 0.15;
125:   }
126: 
127:   93%,
128:   100% {
129:     opacity: 1;
130:   }
131: }

