1: /* ==========================================================================
2:    Phase E3 weather surfaces, the --wx- token namespace
3:    (docs/research.md palette table, "New tokens live in a --wx- namespace
4:    next to --rp and --rv so the report and Money River files never change").
5: 
6:    Band vocabulary (src/lib/verdict.ts owns every band): the five verdict
7:    bands, Critical, Storm warning, Watch, Fair skies, and Clear, carry all
8:    color on these surfaces through their tailwind cp class and
9:    currentColor, so the badge and the strip share one source of band
10:    color (see the .wx-slot rule below). The seven state ladder from the
11:    E3 draft left with weatherState.ts, and its unused palette tokens were
12:    deleted with it.
13: 
14:    The one state accent kept is wx-storm #c02f12, storm vermillion, used
15:    only as a marker: the worst case continuation, the EI cliff line, and
16:    the storm tag. It never sets a band.
17: 
18:    Plus the two grounds every surface sits on: wx-grounds #ffffff (the
19:    halo stroke behind labels on a white panel, read from its own token
20:    so this file never depends on --rp-) and wx-parchment #16273f for
21:    text. Slate on white stays above WCAG AA on every surface here.
22: 
23:    Motion in this file is gated behind prefers-reduced-motion:
24:    no-preference, matching src/index.css, which also zeroes animation
25:    durations globally under prefers-reduced-motion: reduce.
26:    ========================================================================== */
27: 
28: :root {
29:   /* The single state accent: marker only, never a band color. */
30:   --wx-storm: #c02f12;
31: 
32:   /* Grounds and text. */
33:   --wx-grounds: #ffffff;
34:   --wx-parchment: #16273f;
35:   --wx-rule: rgba(22, 39, 63, 0.28);
36:   --wx-text-dim: rgba(22, 39, 63, 0.85);
37:   --wx-text-faint: rgba(22, 39, 63, 0.7);
38: 
39:   /* Utility, deliberately local so nothing here reaches into --rp-. */
40:   --wx-font-display: ui-monospace, "SF Mono", SFMono-Regular, Menlo, Consolas,
41:     "Liberation Mono", monospace;
42:   --wx-font-body: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
43:   --wx-radius: 0;
44: }
45: 
46: /* ==========================================================================
47:    Forecast strip: 12 month tiles, one per verdict band
48:    ========================================================================== */
49: 
50: .wx-strip {
51:   display: block;
52:   width: 100%;
53: }
54: 
55: .wx-strip__svg {
56:   display: block;
57:   width: 100%;
58:   height: auto;
59: }
60: 
61: /* Band colored month slots: the verdict band's own tailwind class sets
62:    the color, fill picks it up through currentColor, and the 22 percent
63:    tint keeps the glyph and the curve legible on top. One source of
64:    band color for the badge and the strip (tailwind.config.js cp). */
65: .wx-slot {
66:   fill: currentColor;
67:   fill-opacity: 0.22;
68: }
69: 
70: .wx-strip__glyph {
71:   fill: currentColor;
72:   font-family: var(--wx-font-body);
73:   font-size: 13px;
74: }
75: 
76: .wx-strip__month {
77:   fill: var(--wx-parchment);
78:   font-family: var(--wx-font-display);
79:   font-size: 9.5px;
80:   letter-spacing: 0.06em;
81: }
82: 
83: .wx-strip__horizon {
84:   fill: var(--wx-text-faint);
85:   font-family: var(--wx-font-display);
86:   font-size: 10px;
87:   letter-spacing: 0.06em;
88: }
89: 
90: .wx-strip__empty {
91:   fill: var(--wx-parchment);
92:   font-family: var(--wx-font-display);
93:   font-size: 11px;
94: }
95: 
96: .wx-strip__placeholder {
97:   fill: none;
98:   stroke: var(--wx-rule);
99:   stroke-dasharray: 4 4;
100: }
101: 
102: /* Curve, grounds, and front ---------------------------------------------- */
103: 
104: .wx-zero-line {
105:   stroke: var(--wx-rule);
106:   stroke-width: 1;
107:   stroke-dasharray: 3 5;
108: }
109: 
110: .wx-history-line {
111:   fill: none;
112:   stroke: var(--wx-text-faint);
113:   stroke-width: 1.5;
114: }
115: 
116: .wx-history-dot {
117:   fill: var(--wx-text-faint);
118: }
119: 
120: .wx-history-legend {
121:   fill: var(--wx-text-faint);
122:   font-family: var(--wx-font-display);
123:   font-size: 9.5px;
124:   letter-spacing: 0.08em;
125: }
126: 
127: .wx-projection-line {
128:   fill: none;
129:   stroke: var(--wx-parchment);
130:   stroke-width: 2.5;
131:   stroke-linecap: round;
132:   stroke-linejoin: round;
133: }
134: 
135: /* The worst case continuation: dashed storm color so it never reads
136:    as the answer key figure on the solid projection line. */
137: .wx-continuation-line {
138:   fill: none;
139:   stroke: var(--wx-storm);
140:   stroke-width: 2;
141:   stroke-dasharray: 7 5;
142:   stroke-linecap: round;
143: }
144: 
145: .wx-front {
146:   stroke-width: 2;
147: }
148: 
149: .wx-front-active {
150:   stroke: var(--wx-storm);
151:   stroke-width: 2.5;
152: }
153: 
154: .wx-front-idle {
155:   stroke: var(--wx-rule);
156:   stroke-dasharray: 4 4;
157: }
158: 
159: /* Pins ------------------------------------------------------------------- */
160: 
161: .wx-pin-stem {
162:   stroke: var(--wx-parchment);
163:   stroke-width: 1.5;
164:   stroke-dasharray: 3 3;
165: }
166: 
167: .wx-pin-dot {
168:   fill: currentColor;
169:   stroke: var(--wx-grounds);
170:   stroke-width: 1.5;
171: }
172: 
173: .wx-pin__label {
174:   fill: var(--wx-parchment);
175:   font-family: var(--wx-font-display);
176:   font-size: 11px;
177:   font-weight: 700;
178:   letter-spacing: 0.04em;
179:   paint-order: stroke;
180:   stroke: var(--wx-grounds);
181:   stroke-width: 3px;
182:   stroke-linejoin: round;
183: }
184: 
185: .wx-pin__label-faint {
186:   fill: var(--wx-text-faint);
187:   font-size: 10px;
188:   font-weight: 400;
189: }
190: 
191: .wx-ei-pin {
192:   fill: var(--wx-storm);
193:   stroke: var(--wx-grounds);
194:   stroke-width: 1.5;
195: }
196: 
197: /* ==========================================================================
198:    Condition bands: the sky legend with the printed threshold sentence.
199:    One band vocabulary (src/lib/verdict.ts): the band's tailwind class on
200:    the list item sets the color, currentColor carries it into the left
201:    rule and the label, and the responsive grid keeps five bands readable
202:    from a phone up to a judging table.
203:    ========================================================================== */
204: 
205: .wx-bands {
206:   display: grid;
207:   grid-template-columns: repeat(auto-fit, minmax(15rem, 1fr));
208:   gap: 6px;
209:   list-style: none;
210:   margin: 0;
211:   padding: 0;
212: }
213: 
214: .wx-band {
215:   display: flex;
216:   align-items: baseline;
217:   gap: 10px;
218:   padding: 8px 12px;
219:   background: rgba(22, 39, 63, 0.04);
220:   border: 2px solid var(--wx-parchment);
221:   border-left: 8px solid currentColor;
222:   border-radius: var(--wx-radius);
223:   box-shadow: 3px 3px 0 0 rgba(22, 39, 63, 0.18);
224:   min-height: 44px;
225: }
226: 
227: .wx-band-active {
228:   box-shadow:
229:     3px 3px 0 0 rgba(22, 39, 63, 0.18),
230:     inset 0 0 0 2px var(--wx-parchment);
231: }
232: 
233: .wx-band__glyph {
234:   font-size: 1rem;
235:   color: var(--wx-parchment);
236: }
237: 
238: .wx-band__body {
239:   display: flex;
240:   flex-wrap: wrap;
241:   align-items: baseline;
242:   gap: 2px 12px;
243:   min-width: 0;
244: }
245: 
246: .wx-band__label {
247:   font-family: var(--wx-font-display);
248:   font-size: 0.8125rem;
249:   letter-spacing: 0.08em;
250:   text-transform: uppercase;
251:   color: currentColor;
252: }
253: 
254: .wx-band__threshold {
255:   font-family: var(--wx-font-body);
256:   font-size: 0.8125rem;
257:   color: var(--wx-text-dim);
258: }
259: 
260: /* ==========================================================================
261:    EI cliff overlay: a marker line that sits over the forecast strip, plus
262:    a dotted second line for the worst case pin. The wiring view wraps the
263:    strip and this overlay in .wx-cliff-wrap, which is the positioning
264:    context; the overlay's own .wx-cliff-set fills that box and the lines
265:     position against it with the slot percent the strip's stripLayout
266:     shares, so the marker lands on the same x the curve uses.
267:    ========================================================================== */
268: 
269: .wx-cliff-wrap {
270:   position: relative;
271: }
272: 
273: .wx-cliff-set {
274:   position: absolute;
275:   inset: 0;
276:   pointer-events: none;
277:   z-index: 2;
278: }
279: 
280: .wx-cliff {
281:   position: absolute;
282:   top: 0;
283:   bottom: 0;
284:   width: 0;
285:   border-left: 2px dashed var(--wx-storm);
286: }
287: 
288: /* The worst case continuation line: dotted and dimmer, so it never
289:    reads as the answer key marker or the solid projection curve. */
290: .wx-cliff-after {
291:   border-left-style: dotted;
292:   opacity: 0.7;
293: }
294: 
295: .wx-cliff__label {
296:   position: absolute;
297:   top: 3px;
298:   left: 0;
299:   white-space: nowrap;
300:   padding: 1px 6px;
301:   border-radius: 2px;
302:   background: var(--wx-storm);
303:   color: var(--wx-grounds);
304:   font-family: var(--wx-font-display);
305:   font-size: 0.625rem;
306:   font-weight: 700;
307:   letter-spacing: 0.1em;
308:   text-transform: uppercase;
309: }
310: 
311: /* On a phone the label is wider than the gap to the strip edge, so it
312:    wraps instead of overflowing the panel. */
313: @media (max-width: 40rem) {
314:   .wx-cliff__label {
315:     white-space: normal;
316:     max-width: 62vw;
317:   }
318: }
319: 
320: /* ==========================================================================
321:    Weather panel: the full width section that composes the strip, the
322:    cliff overlay, the honesty note, and the band key. Local spacing only,
323:    nothing here reaches into the cp or rp namespaces beyond the panel
324:    classes the console already defines.
325:    ========================================================================== */
326: 
327: .wx-panel {
328:   display: flex;
329:   flex-direction: column;
330:   gap: 12px;
331: }
332: 
333: .wx-storm-tag {
334:   display: inline-block;
335:   margin-right: 8px;
336:   padding: 1px 6px;
337:   border: 1px solid var(--wx-storm);
338:   border-radius: 2px;
339:   font-family: var(--wx-font-display);
340:   font-size: 0.625rem;
341:   font-weight: 700;
342:   letter-spacing: 0.1em;
343:   text-transform: uppercase;
344:   color: var(--wx-storm);
345:   vertical-align: 1px;
346: }
347: 
348: .wx-honesty {
349:   display: flex;
350:   flex-wrap: wrap;
351:   align-items: baseline;
352:   gap: 4px 10px;
353:   margin: 0;
354:   font-family: var(--wx-font-body);
355:   font-size: 0.8125rem;
356:   line-height: 1.5;
357:   color: var(--wx-text-dim);
358: }
359: 
360: .wx-honesty__swatch {
361:   align-self: center;
362:   width: 22px;
363:   height: 0;
364:   border-top: 2px solid var(--wx-text-faint);
365: }
366: 
