27:   src: url('./assets/fonts/silkscreen-700.woff2') format('woff2');
28: }
29: 
30: html,
31: body,
32: #root {
33:   min-height: 100%;
34: }
35: 
36: body {
37:   @apply bg-void text-ink font-sans antialiased;
38: }
39: 
40: /* ==========================================================================
41:    Report tokens: a pixel game weather station read in daylight. Six named
42:    colors, three type roles, one spacing scale. No external fonts, so the
43:    booth machine never reaches the network. The values run light: a pale
44:    sky tinted ground, white panel cards, dark slate ink, and the five
45:    verdict band hues re-tuned so every band label clears WCAG AA on both
46:    the ground and a panel.
47:    ========================================================================== */
48: 
49: :root {
50:   /* Palette (named hex values, the whole report runs on these six). */
51:   --rp-void: #eaf1fb; /* daylight ground, pale sky paper */
52:   --rp-paper: #16273f; /* slate ink, every piece of primary text */
53:   --rp-rule: #8496b3; /* blueprint rule on light */
54:   --rp-verified: #0a7a5a; /* provenance teal, locked and checked */
55:   --rp-money: #8f5502; /* ledger amber, discretionary dollars */
56:   --rp-stamp: #c02f12; /* audit stamp red, warnings and mismatches */
57: 
58:   /* Derived tones (solid over the daylight ground, so contrast holds). */
59:   --rp-panel: #ffffff;
60:   --rp-panel-strong: #f2f7fd;
61:   --rp-text-dim: #3f5270;
62:   --rp-text-faint: #56688a;
63:   --rp-verified-dim: rgba(10, 122, 90, 0.55);
64:   --rp-verified-ghost: rgba(10, 122, 90, 0.1);
65:   --rp-money-dim: rgba(143, 85, 2, 0.55);
66:   --rp-money-ghost: rgba(143, 85, 2, 0.1);
67:   --rp-stamp-ghost: rgba(192, 47, 18, 0.1);
68:   --rp-gridline: rgba(132, 150, 179, 0.3);
69: 
70:   /* Type roles. Display and utility share one mono stack in two registers:
71:      heavy tight numerals for the readouts, tiny tracked caps for labels.
72:      The pixel face is the fourth role: chrome only, never a number. */
73:   --rp-font-display: ui-monospace, "SF Mono", SFMono-Regular, Menlo, Consolas,
74:     "Liberation Mono", monospace;
75:   --rp-font-body: system-ui, -apple-system, "Segoe UI", Roboto,
76:     "Helvetica Neue", Arial, sans-serif;
77:   --rp-font-utility: var(--rp-font-display);
78:   --rp-font-pixel: 'Silkscreen', ui-monospace, "SF Mono", Menlo, monospace;
79: 
80:   /* Spacing scale. */
81:   --rp-s1: 0.25rem;
82:   --rp-s2: 0.5rem;
83:   --rp-s3: 0.75rem;
84:   --rp-s4: 1rem;
85:   --rp-s5: 1.5rem;
86:   --rp-s6: 2rem;
87:   --rp-s7: 3rem;
88:   --rp-s8: 4.5rem;
89: 
90:   --rp-radius: 0;
91:   --rp-max: 72rem;
92: }
93: 
94: /* ==========================================================================
95:    Base: visible keyboard focus everywhere, smooth anchors, quiet motion.
96:    ========================================================================== */
97: 
98: :where(a, button, summary, [tabindex]):focus-visible {
99:   outline: 2px solid var(--rp-paper);
100:   outline-offset: 2px;
101:   box-shadow: 0 0 0 4px rgba(13, 110, 168, 0.4);
102: }
103: 
104: html {
105:   scroll-behavior: smooth;
106: }
107: 
108: ::selection {
109:   background: var(--rp-verified);
110:   color: #ffffff;
111: }
112: 
113: @media (prefers-reduced-motion: reduce) {
114:   html {
115:     scroll-behavior: auto;
116:   }
117: 
118:   *,
119:   *::before,
120:   *::after {
121:     animation-duration: 0.001ms !important;
122:     animation-iteration-count: 1 !important;
123:     transition-duration: 0.001ms !important;
124:   }
125: }
126: 
127: /* ==========================================================================
128:    Report shell
129:    ========================================================================== */
